mapper.select:
SELECT o.order_id, a.id AS account_id, i.ticker AS symbol, o.side, o.quantity, o.limit_price AS price, o.executed_price, o.status, o.idempotency_key, o.placed_at AS created_on FROM Orders o JOIN Accounts a ON a.account_id = o.account_id JOIN Instruments i ON i.instrument_id = o.instrument_id WHERE a.id = #{accountId}
AND o.status = #{status}::order_status_enum
AND o.placed_at >= #{from}
AND o.placed_at <= #{to}
ORDER BY o.placed_at DESC
